class Solution {public double findMedianSortedArrays(int[] a,int[] b){if(a.length>b.length)return findMedianSortedArrays(b,a);int n=a.length,m=b.length,lo=0,hi=n;while(lo<=hi){int i=(lo+hi)/2,j=(n+m+1)/2-i;int al=i==0?Integer.MIN_VALUE:a[i-1],ar=i==n?Integer.MAX_VALUE:a[i];int bl=j==0?Integer.MIN_VALUE:b[j-1],br=j==m?Integer.MAX_VALUE:b[j];if(al<=br&&bl<=ar){if((n+m)%2==1)return Math.max(al,bl);return ((long)Math.max(al,bl)+Math.min(ar,br))/2.0;}if(al>br)hi=i-1;else lo=i+1;}throw new IllegalArgumentException();}}